  [ "$status" -eq 0 ]
  [ "$output" = "false" ]
  dokku http-auth:enable "$APP"
  run dokku http-auth:report "$APP" --http-auth-enabled
  [ "$status" -eq 0 ]
  [ "$output" = "true" ]
