  [ "$status" -eq 0 ]
  [ -z "$output" ]
  dokku http-auth:enable "$APP"
  dokku http-auth:add-allowed-ip "$APP" 10.0.0.1
  run dokku http-auth:report "$APP" --http-auth-allowed-ips
  [ "$status" -eq 0 ]
  [ "$output" = "10.0.0.1" ]
}

@test "(http-auth:report) --http-auth-users is empty but successful with no users" {
  run dokku http-auth:report "$APP" --http-auth-users
  [ "$status" -eq 0 ]
  [ -z "$output" ]
}

@test "(http-auth:report) --http-auth-users lists users" {
  dokku http-auth:enable "$APP" u1 pass1
  dokku http-auth:add-user "$APP" u2 pass2
  run dokku http-auth:report "$APP" --http-auth-users
  [ "$status" -eq 0 ]
  [ "$output" = "u1 u2" ]
}

@test "(http-auth:report) rejects an invalid flag" {
  run dokku http-auth:report "$APP" --invalid-flag
  [ "$status" -ne 0 ]
  [[ "$output" == *"Invalid flag passed, valid flags:"* ]]
}

@test "(http-auth:report) fails for a missing app" {
  run dokku http-auth:report hatest-no-such-app
  [ "$status" -ne 0 ]
  [[ "$output" == *"does not exist"* ]]
}

@test "(http-auth:report) --format json emits a json object" {
  run dokku http-auth:report "$APP" --format json
  [ "$status" -eq 0 ]
  [[ "$output" == *'"enabled":"false"'* ]]
  [[ "$output" == *'"allowed-ips":""'* ]]
  [[ "$output" == *'"domains":""'* ]]
  [[ "$output" == *'"users":""'* ]]

  dokku http-auth:enable "$APP"
  dokku http-auth:add-allowed-ip "$APP" 10.0.0.1

  run dokku http-auth:report "$APP" --format json
  [ "$status" -eq 0 ]
  [[ "$output" == *'"enabled":"true"'* ]]
  [[ "$output" == *'"allowed-ips":"10.0.0.1"'* ]]
}

@test "(http-auth:report) --format json rejects an info flag" {
  run dokku http-auth:report "$APP" --format json --http-auth-enabled
  [ "$status" -ne 0 ]
  [[ "$output" == *"--format flag cannot be specified when specifying an info flag"* ]]
}

@test "(http-auth:report) without an app emits one json object per app" {
  run dokku http-auth:report --format json
  [ "$status" -eq 0 ]
  [[ "$output" == *'"enabled":"false"'* ]]

  # every emitted line is a valid JSON object
  run /bin/bash -c "dokku http-auth:report --format json | jq -e . >/dev/null"
  [ "$status" -eq 0 ]
}

@test "(http-auth:report) --global --format json returns an empty object" {
  run dokku http-auth:report --global --format json
  [ "$status" -eq 0 ]
  [ "$output" = "{}" ]
}

@test "(dokku report) includes an http-auth section" {
  run dokku report "$APP"
  [ "$status" -eq 0 ]
  [[ "$output" == *"http-auth information"* ]]
}

#!/usr/bin/env bats
# Exercises the privileged bin/set-htpasswd helper directly, including its
# app-name validation - the security boundary that keeps every write confined
# to /etc/nginx/http-auth.

load 'test_helper'

setup() {
  APP="$(new_app_name)"
}

teardown() {
  $SUDO "$(set_htpasswd_helper)" remove "$APP" 2>/dev/null || true
}

@test "(set-htpasswd) write round-trips stdin to the app's htpasswd with mode 644" {
  echo 'u1:$6$hash' | $SUDO "$(set_htpasswd_helper)" write "$APP"
  $SUDO test -f "$(htpasswd_path "$APP")"
  [ "$(htpasswd_contents "$APP")" = 'u1:$6$hash' ]
  [ "$($SUDO stat -c '%a' "$(htpasswd_path "$APP")")" = "644" ]
  [ "$($SUDO stat -c '%a' "$(htpasswd_dir "$APP")")" = "755" ]
}

@test "(set-htpasswd) ensure creates an empty htpasswd without clobbering an existing one" {
  echo 'u1:$6$hash' | $SUDO "$(set_htpasswd_helper)" write "$APP"
  $SUDO "$(set_htpasswd_helper)" ensure "$APP"
  [ "$(htpasswd_contents "$APP")" = 'u1:$6$hash' ]
}

@test "(set-htpasswd) remove deletes the app's htpasswd directory" {
  echo 'u1:$6$hash' | $SUDO "$(set_htpasswd_helper)" write "$APP"
  $SUDO test -d "$(htpasswd_dir "$APP")"
  $SUDO "$(set_htpasswd_helper)" remove "$APP"
  $SUDO test ! -d "$(htpasswd_dir "$APP")"
}

@test "(set-htpasswd) rejects an app name containing a slash" {
  run bash -c "echo pwned | $(set_htpasswd_helper) write 'foo/bar'"
  [ "$status" -ne 0 ]
  [[ "$output" == *"Invalid app name"* ]]
}

@test "(set-htpasswd) rejects a path-traversal app name and writes nothing outside the tree" {
  run bash -c "echo pwned | $(set_htpasswd_helper) write '../../../../../../etc/cron.d/pwn'"
  [ "$status" -ne 0 ]
  test ! -f /etc/cron.d/pwn
}

@test "(set-htpasswd) rejects an empty app name" {
  run bash -c "echo pwned | $(set_htpasswd_helper) write ''"
  [ "$status" -ne 0 ]
  [[ "$output" == *"Missing app name"* ]]
}

