  [ "$status" -eq 0 ]
  [[ "$output" == *"Deprecated: Please use http-auth:enable"* ]]
  assert_enabled "$APP"
}

@test "(http-auth:enable) records the enabled property" {
  dokku http-auth:enable "$APP"
  [ "$(http_auth_property "$APP" enabled)" = "true" ]
}

#!/usr/bin/env bats

load 'test_helper'

setup() {
  APP="$(new_app_name)"
  APP2=""
  create_app "$APP"
  dokku http-auth:enable "$APP"
}

teardown() {
  cleanup_app "$APP"
  if [ -n "$APP2" ]; then
    cleanup_app "$APP2"
  fi
}

@test "(http-auth:add-user) adds an htpasswd entry with a sha-512 hash" {
  run dokku http-auth:add-user "$APP" u1 pass1
  [ "$status" -eq 0 ]
  [[ "$output" == *"Adding u1 to basic auth list"* ]]
  htpasswd_contents "$APP" | grep -q '^u1:\$6\$'
}

@test "(http-auth:add-user) renders the auth_basic block into the config" {
  dokku http-auth:add-user "$APP" u1 pass1
  run http_auth_conf "$APP"
  [[ "$output" == *"auth_basic"* ]]
  [[ "$output" == *"auth_basic_user_file $(htpasswd_path "$APP");"* ]]
}

@test "(http-auth:add-user) replaces the password of an existing user" {
  dokku http-auth:add-user "$APP" u1 pass1
  local first_entry="$(htpasswd_contents "$APP" | grep '^u1:')"
  dokku http-auth:add-user "$APP" u1 pass2
  local second_entry="$(htpasswd_contents "$APP" | grep '^u1:')"
  [ "$(htpasswd_contents "$APP" | grep -c '^u1:')" -eq 1 ]
  [ "$first_entry" != "$second_entry" ]
}

@test "(http-auth:add-user) on a disabled app enables auth" {
  dokku http-auth:disable "$APP"
  assert_disabled "$APP"
  run dokku http-auth:add-user "$APP" u1 pass1
  [ "$status" -eq 0 ]
  assert_enabled "$APP"
  htpasswd_contents "$APP" | grep -q '^u1:\$6\$'
  run http_auth_conf "$APP"
  [[ "$output" == *"auth_basic"* ]]
}

@test "(http-auth:add-user) enables auth on an app that never had it enabled" {
  APP2="$(new_app_name)"
  create_app "$APP2"
  run dokku http-auth:add-user "$APP2" u1 pass1
  [ "$status" -eq 0 ]
  assert_enabled "$APP2"
  run http_auth_conf "$APP2"
  [[ "$output" == *"auth_basic"* ]]
}

@test "(http-auth:add-user) fails when the username is missing" {
  run dokku http-auth:add-user "$APP"
  [ "$status" -ne 0 ]
  [[ "$output" == *"Missing username"* ]]
}

@test "(http-auth:add-user) fails when the password is missing" {
  run dokku http-auth:add-user "$APP" u1
  [ "$status" -ne 0 ]
  [[ "$output" == *"Missing password"* ]]
}

@test "(http-auth:remove-user) removes the htpasswd entry" {
  dokku http-auth:add-user "$APP" u1 pass1
  dokku http-auth:add-user "$APP" u2 pass2
  run dokku http-auth:remove-user "$APP" u1
  [ "$status" -eq 0 ]
  [[ "$output" == *"Removing u1 from basic auth list"* ]]
  run dokku http-auth:report "$APP" --http-auth-users
  [ "$status" -eq 0 ]
  [ "$output" = "u2" ]
}

@test "(http-auth:remove-user) removing the last user drops the auth_basic block" {
  dokku http-auth:add-user "$APP" u1 pass1
  dokku http-auth:remove-user "$APP" u1
  run http_auth_conf "$APP"
  [[ "$output" != *"auth_basic"* ]]
}

@test "(http-auth:remove-user) prunes a user on a disabled app without enabling auth" {
  dokku http-auth:add-user "$APP" u1 pass1
  dokku http-auth:disable "$APP"
  run dokku http-auth:remove-user "$APP" u1
  [ "$status" -eq 0 ]
  # removing config must not turn auth back on, and must not resurrect the include
  assert_disabled "$APP"
  $SUDO test ! -f "$(http_auth_conf_path "$APP")"
  [ -z "$(htpasswd_contents "$APP")" ]
}

@test "(http-auth:remove-user) fails when the username is missing" {
  run dokku http-auth:remove-user "$APP"
  [ "$status" -ne 0 ]
  [[ "$output" == *"Missing username"* ]]
}

#!/usr/bin/env bats

load 'test_helper'

setup() {
  APP="$(new_app_name)"
  create_app "$APP"
  # attach vhosts so add-domain/set-domains validation (which checks the app's
  # actual domains) has something to match; the suite never deploys.
  dokku domains:add "$APP" a.example.com b.example.com >/dev/null
  dokku http-auth:enable "$APP" u1 pass1
}

teardown() {
  cleanup_app "$APP"
}

@test "(http-auth:add-domain) renders a host-gated realm variable" {
  run dokku http-auth:add-domain "$APP" a.example.com
  [ "$status" -eq 0 ]
  [[ "$output" == *"Adding a.example.com to auth domain list"* ]]
  run http_auth_conf "$APP"
  [[ "$output" == *'set $dokku_auth_realm off;'* ]]
  [[ "$output" == *'if ($host = "a.example.com") {'* ]]
  [[ "$output" == *'set $dokku_auth_realm "Restricted";'* ]]
  [[ "$output" == *'auth_basic           $dokku_auth_realm;'* ]]
  [[ "$output" == *"auth_basic_user_file $(htpasswd_path "$APP");"* ]]
  # the plain app-wide realm must not be present when domains are set
  [[ "$output" != *'auth_basic           "Restricted";'* ]]
}

@test "(http-auth) with no domains renders the plain auth_basic block" {
  run http_auth_conf "$APP"
  [[ "$output" == *'auth_basic           "Restricted";'* ]]
  [[ "$output" != *'dokku_auth_realm'* ]]
}

@test "(http-auth:add-domain) renders one if block per domain" {
  dokku http-auth:add-domain "$APP" a.example.com
  dokku http-auth:add-domain "$APP" b.example.com
  run http_auth_conf "$APP"
  [[ "$output" == *'if ($host = "a.example.com") {'* ]]
  [[ "$output" == *'if ($host = "b.example.com") {'* ]]
}

@test "(http-auth:add-domain) is idempotent for duplicate domains" {
  dokku http-auth:add-domain "$APP" a.example.com
  run dokku http-auth:add-domain "$APP" a.example.com
  [ "$status" -eq 0 ]
  [ "$(http_auth_conf "$APP" | grep -c 'if (\$host = "a.example.com") {')" -eq 1 ]
  run dokku http-auth:report "$APP" --http-auth-domains
  [ "$status" -eq 0 ]
  [ "$output" = "a.example.com" ]
}

@test "(http-auth:add-domain) lowercases the domain" {
  run dokku http-auth:add-domain "$APP" A.Example.COM
  [ "$status" -eq 0 ]
  run http_auth_conf "$APP"
  [[ "$output" == *'if ($host = "a.example.com") {'* ]]
  [[ "$output" != *"A.Example.COM"* ]]
  run dokku http-auth:report "$APP" --http-auth-domains
  [ "$output" = "a.example.com" ]
}

@test "(http-auth:add-domain) fails when the domain is not attached to the app" {
  run dokku http-auth:add-domain "$APP" nope.example.com
  [ "$status" -ne 0 ]
  [[ "$output" == *"nope.example.com is not a domain of $APP"* ]]
}

@test "(http-auth:add-domain) fails when the domain is missing" {
  run dokku http-auth:add-domain "$APP"
  [ "$status" -ne 0 ]
  [[ "$output" == *"Missing domain"* ]]
}

@test "(http-auth:add-domain) on a disabled app implicitly enables auth" {
  dokku http-auth:disable "$APP"
  assert_disabled "$APP"
  run dokku http-auth:add-domain "$APP" a.example.com
  [ "$status" -eq 0 ]
  assert_enabled "$APP"
  run http_auth_conf "$APP"
